-- seed.sql
-- Deterministic seed data for the soccer RSVP + rating app.
-- Roster rows only (user_id null); no auth.users required.
-- Order matters: players -> games -> appearances -> ratings.

begin;

-- ---------------------------------------------------------------------------
-- Players (roster): 20 rows, 16 with phones, 2 opted out, all unlinked.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- Games: 10 played games across the last ~10 weeks on varied days/times.
-- ratings_close_at is left null so the trigger sets starts_at + 48h.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- Appearances (who actually showed up). Inserted BEFORE ratings so the
-- appearance-exists trigger accepts every rating below.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- RSVPs: attendees marked 'in', plus a few 'out'/'maybe' from others.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- Ratings: overall weighted 3-4, speed/intensity 1-5, a few comments.
-- Every rater has an appearance for that game. Game 6 has <40% response
-- (5 ratings / 15 appearances = 0.33) to exercise is_low_response.
-- ---------------------------------------------------------------------------

commit;

